const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const mod = b.createModule(.{
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    const exe = b.addExecutable(.{ .name = "kvhttp", .root_module = mod });
    b.installArtifact(exe);

    const run = b.addRunArtifact(exe);
    if (b.args) |args| run.addArgs(args);
    b.step("run", "Run the server").dependOn(&run.step);

    const tests = b.addTest(.{ .root_module = mod });
    b.step("test", "Run unit tests").dependOn(&b.addRunArtifact(tests).step);
}

//! Thread-safe in-memory key-value store. Keys and values are owned by the store.

const Store = @This();

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

gpa: Allocator,
mutex: Io.Mutex = .init,
map: std.StringHashMapUnmanaged([]u8) = .empty,

pub fn init(gpa: Allocator) Store {
    return .{ .gpa = gpa };
}

pub fn deinit(self: *Store) void {
    var it = self.map.iterator();
    while (it.next()) |entry| {
        self.gpa.free(entry.key_ptr.*);
        self.gpa.free(entry.value_ptr.*);
    }
    self.map.deinit(self.gpa);
    self.* = undefined;
}

/// Stores `value`, taking ownership of it (it must have been allocated with
/// the store's allocator). Returns true if the key was new.
pub fn put(self: *Store, io: Io, key: []const u8, value: []u8) Allocator.Error!bool {
    // Allocate the key copy before taking the lock to keep the critical section short.
    const owned_key = try self.gpa.dupe(u8, key);
    var key_used = false;
    defer if (!key_used) self.gpa.free(owned_key);

    self.mutex.lockUncancelable(io);
    defer self.mutex.unlock(io);

    const gop = self.map.getOrPut(self.gpa, key) catch |err| {
        self.gpa.free(value);
        return err;
    };
    if (gop.found_existing) {
        self.gpa.free(gop.value_ptr.*);
    } else {
        gop.key_ptr.* = owned_key;
        key_used = true;
    }
    gop.value_ptr.* = value;
    return !gop.found_existing;
}

/// Returns a copy of the value for `key`, allocated with `gpa`, or null if absent.
pub fn getCopy(self: *Store, io: Io, gpa: Allocator, key: []const u8) Allocator.Error!?[]u8 {
    self.mutex.lockUncancelable(io);
    defer self.mutex.unlock(io);

    const value = self.map.get(key) orelse return null;
    return try gpa.dupe(u8, value);
}

/// Removes `key`. Returns true if it was present.
pub fn delete(self: *Store, io: Io, key: []const u8) bool {
    const removed = blk: {
        self.mutex.lockUncancelable(io);
        defer self.mutex.unlock(io);
        break :blk self.map.fetchRemove(key);
    } orelse return false;
    self.gpa.free(removed.key);
    self.gpa.free(removed.value);
    return true;
}

/// Returns every key sorted ascending, serialized as a compact JSON array.
/// Keys are restricted to `[A-Za-z0-9_-]`, so no escaping is required.
pub fn keysJson(self: *Store, io: Io, gpa: Allocator) Allocator.Error![]u8 {
    var arena_state: std.heap.ArenaAllocator = .init(gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const keys = blk: {
        self.mutex.lockUncancelable(io);
        defer self.mutex.unlock(io);

        const keys = try arena.alloc([]const u8, self.map.count());
        var it = self.map.keyIterator();
        var i: usize = 0;
        while (it.next()) |k| : (i += 1) keys[i] = try arena.dupe(u8, k.*);
        break :blk keys;
    };

    std.mem.sortUnstable([]const u8, keys, {}, lessThan);

    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(gpa);
    try out.append(gpa, '[');
    for (keys, 0..) |k, i| {
        if (i != 0) try out.append(gpa, ',');
        try out.append(gpa, '"');
        try out.appendSlice(gpa, k);
        try out.append(gpa, '"');
    }
    try out.append(gpa, ']');
    return out.toOwnedSlice(gpa);
}

fn lessThan(_: void, a: []const u8, b: []const u8) bool {
    return std.mem.order(u8, a, b) == .lt;
}

const testing = std.testing;

test "put, get, delete, list" {
    const io = testing.io;
    const gpa = testing.allocator;
    var store: Store = .init(gpa);
    defer store.deinit();

    try testing.expect(try store.put(io, "b", try gpa.dupe(u8, "2")));
    try testing.expect(try store.put(io, "a", try gpa.dupe(u8, "1")));
    try testing.expect(!try store.put(io, "b", try gpa.dupe(u8, "two")));

    const v = (try store.getCopy(io, gpa, "b")).?;
    defer gpa.free(v);
    try testing.expectEqualStrings("two", v);
    try testing.expect(try store.getCopy(io, gpa, "zz") == null);

    const json = try store.keysJson(io, gpa);
    defer gpa.free(json);
    try testing.expectEqualStrings("[\"a\",\"b\"]", json);

    try testing.expect(store.delete(io, "a"));
    try testing.expect(!store.delete(io, "a"));
}

test "empty list" {
    var store: Store = .init(testing.allocator);
    defer store.deinit();
    const json = try store.keysJson(testing.io, testing.allocator);
    defer testing.allocator.free(json);
    try testing.expectEqualStrings("[]", json);
}

//! Minimal HTTP/1.1 request parsing and response serialization.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

pub const max_body_size = 1024 * 1024;
/// Upper bound for the request head and for each chunk-size line. The
/// connection reader's buffer must be at least this large.
pub const max_head_size = 64 * 1024;

pub const Status = enum(u16) {
    ok = 200,
    created = 201,
    no_content = 204,
    bad_request = 400,
    not_found = 404,
    method_not_allowed = 405,
    content_too_large = 413,
    request_header_fields_too_large = 431,
    internal_server_error = 500,

    pub fn phrase(status: Status) []const u8 {
        return switch (status) {
            .ok => "OK",
            .created => "Created",
            .no_content => "No Content",
            .bad_request => "Bad Request",
            .not_found => "Not Found",
            .method_not_allowed => "Method Not Allowed",
            .content_too_large => "Content Too Large",
            .request_header_fields_too_large => "Request Header Fields Too Large",
            .internal_server_error => "Internal Server Error",
        };
    }
};

pub const Request = struct {
    method: []const u8,
    /// Request target with any query string removed.
    path: []const u8,
    body: []u8,
};

pub const Response = struct {
    status: Status,
    body: []const u8 = "",
    content_type: ?[]const u8 = null,
    allow: ?[]const u8 = null,

    pub fn write(res: Response, w: *Io.Writer) Io.Writer.Error!void {
        try w.print("HTTP/1.1 {d} {s}\r\nConnection: close\r\n", .{ @intFromEnum(res.status), res.status.phrase() });
        if (res.allow) |allow| try w.print("Allow: {s}\r\n", .{allow});
        if (res.content_type) |ct| {
            try w.print("Content-Type: {s}\r\n", .{ct});
        } else if (res.body.len != 0) {
            try w.writeAll("Content-Type: application/octet-stream\r\n");
        }
        try w.print("Content-Length: {d}\r\n\r\n", .{res.body.len});
        try w.writeAll(res.body);
        try w.flush();
    }
};

pub const ParseError = error{
    /// Malformed request; answer 400.
    BadRequest,
    /// Request head exceeds `max_head_size`; answer 431.
    HeaderTooLarge,
    /// Body exceeds `max_body_size`; answer 413.
    ContentTooLarge,
    /// The underlying connection failed; no response can be delivered.
    ReadFailed,
    OutOfMemory,
};

pub fn errorStatus(err: ParseError) ?Status {
    return switch (err) {
        error.BadRequest => .bad_request,
        error.HeaderTooLarge => .request_header_fields_too_large,
        error.ContentTooLarge => .content_too_large,
        error.OutOfMemory => .internal_server_error,
        error.ReadFailed => null,
    };
}

/// Reads one request from `r`. Returns null if the peer closed the
/// connection without sending anything but whitespace.
///
/// `method` and `path` are allocated with `arena`; `body` is allocated with
/// `gpa` and owned by the caller.
pub fn readRequest(arena: Allocator, gpa: Allocator, r: *Io.Reader) ParseError!?Request {
    std.debug.assert(r.buffer.len >= max_head_size);

    const head = try readHead(r) orelse return null;

    var lines = std.mem.splitSequence(u8, head, "\r\n");
    const request_line = lines.first();
    var parts = std.mem.splitScalar(u8, request_line, ' ');
    const method = parts.next().?;
    const target = parts.next() orelse return error.BadRequest;
    _ = parts.next() orelse return error.BadRequest;
    if (parts.next() != null) return error.BadRequest;

    var content_length: ?[]const u8 = null;
    var transfer_encoding: []const u8 = "";
    while (lines.next()) |line| {
        if (line.len == 0) continue;
        const colon = std.mem.indexOfScalar(u8, line, ':') orelse return error.BadRequest;
        const name = trim(line[0..colon]);
        const value = trim(line[colon + 1 ..]);
        if (std.ascii.eqlIgnoreCase(name, "content-length")) {
            content_length = value;
        } else if (std.ascii.eqlIgnoreCase(name, "transfer-encoding")) {
            transfer_encoding = value;
        }
    }

    const path_end = std.mem.indexOfScalar(u8, target, '?') orelse target.len;
    // Copy before reading the body: further reads may overwrite the buffer `head` points into.
    const owned_method = try arena.dupe(u8, method);
    const owned_path = try arena.dupe(u8, target[0..path_end]);
    const is_chunked = std.ascii.indexOfIgnoreCase(transfer_encoding, "chunked") != null;
    const length = if (content_length) |cl| try parseContentLength(cl) else null;

    const body = if (is_chunked)
        try readChunkedBody(gpa, r)
    else if (length) |n|
        try readSizedBody(gpa, r, n)
    else
        try gpa.alloc(u8, 0);

    return .{ .method = owned_method, .path = owned_path, .body = body };
}

/// Returns the request head including its terminating blank line, consumed
/// from `r`. The slice is valid until the next read from `r`.
fn readHead(r: *Io.Reader) ParseError!?[]const u8 {
    const terminator = "\r\n\r\n";
    var search_from: usize = 0;
    while (true) {
        const buffered = r.buffered();
        if (std.mem.indexOfPos(u8, buffered, search_from, terminator)) |i| {
            const head = buffered[0 .. i + terminator.len];
            r.toss(head.len);
            return head;
        }
        if (buffered.len >= max_head_size) return error.HeaderTooLarge;
        search_from = buffered.len -| (terminator.len - 1);
        r.fillMore() catch |err| switch (err) {
            error.EndOfStream => {
                if (trim(r.buffered()).len == 0) return null;
                return error.BadRequest;
            },
            error.ReadFailed => return error.ReadFailed,
        };
    }
}

fn parseContentLength(text: []const u8) ParseError!u64 {
    if (text.len == 0) return error.BadRequest;
    for (text) |c| if (!std.ascii.isDigit(c)) return error.BadRequest;
    // All digits: the only possible failure is overflow, which is simply "too large".
    return std.fmt.parseInt(u64, text, 10) catch std.math.maxInt(u64);
}

fn readSizedBody(gpa: Allocator, r: *Io.Reader, length: u64) ParseError![]u8 {
    if (length > max_body_size) {
        // Drain the body so the client reliably receives the error response.
        r.discardAll64(length) catch |err| return mapReadError(err);
        return error.ContentTooLarge;
    }
    const body = try gpa.alloc(u8, @intCast(length));
    errdefer gpa.free(body);
    r.readSliceAll(body) catch |err| return mapReadError(err);
    return body;
}

fn readChunkedBody(gpa: Allocator, r: *Io.Reader) ParseError![]u8 {
    var body: std.ArrayList(u8) = .empty;
    errdefer body.deinit(gpa);
    while (true) {
        const line = try takeLine(r);
        const size_text = trim(line[0 .. std.mem.indexOfScalar(u8, line, ';') orelse line.len]);
        const size = std.fmt.parseInt(usize, size_text, 16) catch |err| switch (err) {
            error.Overflow => return error.ContentTooLarge,
            error.InvalidCharacter => return error.BadRequest,
        };
        if (size == 0) {
            // Consume optional trailers up to the terminating blank line.
            while ((try takeLine(r)).len != 0) {}
            return body.toOwnedSlice(gpa);
        }
        if (body.items.len + size > max_body_size) return error.ContentTooLarge;
        r.readSliceAll(try body.addManyAsSlice(gpa, size)) catch |err| return mapReadError(err);
        r.discardAll(2) catch |err| return mapReadError(err);
    }
}

/// Takes one CRLF-terminated line, returning it without the CRLF.
fn takeLine(r: *Io.Reader) ParseError![]const u8 {
    var search_from: usize = 0;
    while (true) {
        const buffered = r.buffered();
        if (std.mem.indexOfPos(u8, buffered, search_from, "\r\n")) |i| {
            r.toss(i + 2);
            return buffered[0..i];
        }
        if (buffered.len >= max_head_size) return error.BadRequest;
        search_from = buffered.len -| 1;
        r.fillMore() catch |err| return mapReadError(err);
    }
}

fn mapReadError(err: Io.Reader.Error) ParseError {
    return switch (err) {
        error.EndOfStream => error.BadRequest,
        error.ReadFailed => error.ReadFailed,
    };
}

fn trim(s: []const u8) []const u8 {
    return std.mem.trim(u8, s, " \t\r\n\x0b\x0c");
}

const testing = std.testing;

/// Parses `input` with all allocations in `arena`.
fn parseFixed(arena: Allocator, input: []const u8) ParseError!?Request {
    const buf = try arena.alloc(u8, max_head_size);
    var src: Io.Reader = .fixed(input);
    var r = src.limited(.unlimited, buf);
    return readRequest(arena, arena, &r.interface);
}

fn expectRequest(input: []const u8, method: []const u8, path: []const u8, body: []const u8) !void {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    const req = (try parseFixed(arena.allocator(), input)).?;
    try testing.expectEqualStrings(method, req.method);
    try testing.expectEqualStrings(path, req.path);
    try testing.expectEqualStrings(body, req.body);
}

fn expectParseError(expected: ParseError, input: []const u8) !void {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    try testing.expectError(expected, parseFixed(arena.allocator(), input));
}

fn expectNoRequest(input: []const u8) !void {
    var arena: std.heap.ArenaAllocator = .init(testing.allocator);
    defer arena.deinit();
    try testing.expectEqual(null, try parseFixed(arena.allocator(), input));
}

test "parse simple requests" {
    try expectRequest("GET /health HTTP/1.1\r\nHost: x\r\n\r\n", "GET", "/health", "");
    try expectRequest("PUT /kv/a?x=1 HTTP/1.1\r\nContent-Length: 5\r\n\r\nhello", "PUT", "/kv/a", "hello");
    try expectRequest("PUT /kv/a HTTP/1.1\r\ncontent-length:  3 \r\n\r\nabcdef", "PUT", "/kv/a", "abc");
}

test "parse chunked body" {
    try expectRequest(
        "PUT /kv/a HTTP/1.1\r\nTransfer-Encoding: Chunked\r\n\r\n5;ext=1\r\nhello\r\n6\r\n world\r\n0\r\nX-T: 1\r\n\r\n",
        "PUT",
        "/kv/a",
        "hello world",
    );
}

test "parse errors" {
    try expectNoRequest("");
    try expectNoRequest(" \r\n");
    try expectParseError(error.BadRequest, "GET /\r\n\r\n");
    try expectParseError(error.BadRequest, "GET / HTTP/1.1 x\r\n\r\n");
    try expectParseError(error.BadRequest, "GET / HTTP/1.1\r\nnocolon\r\n\r\n");
    try expectParseError(error.BadRequest, "GET / HTTP/1.1\r\nHost: x\r\n");
    try expectParseError(error.BadRequest, "PUT / HTTP/1.1\r\nContent-Length: -1\r\n\r\n");
    try expectParseError(error.BadRequest, "PUT / HTTP/1.1\r\nContent-Length: 10\r\n\r\nshort");
    try expectParseError(error.BadRequest, "PUT / HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\nzz\r\n");
    try expectParseError(error.BadRequest, "PUT / HTTP/1.1\r\nContent-Length: 2000000\r\n\r\nabc");
}

test "oversized head" {
    const input = try testing.allocator.alloc(u8, max_head_size + 10);
    defer testing.allocator.free(input);
    @memset(input, 'a');
    try expectParseError(error.HeaderTooLarge, input);
}

test "response serialization" {
    var buf: [256]u8 = undefined;
    var w: Io.Writer = .fixed(&buf);
    try (Response{ .status = .ok, .body = "ok", .content_type = "text/plain" }).write(&w);
    try testing.expectEqualStrings(
        "HTTP/1.1 200 OK\r\nConnection: close\r\nContent-Type: text/plain\r\nContent-Length: 2\r\n\r\nok",
        w.buffered(),
    );
}

//! kvhttp: a minimal in-memory HTTP/1.1 key-value server (see SPEC.md).
//!
//! Usage: kvhttp <port>
//! Listens on 127.0.0.1:<port>; each connection serves a single request.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;
const net = std.Io.net;

const http = @import("http.zig");
const routes = @import("routes.zig");
const Store = @import("Store.zig");

const log = std.log.scoped(.kvhttp);

pub const std_options: std.Options = .{ .log_level = .warn };

const read_buffer_size = http.max_head_size;
const write_buffer_size = 16 * 1024;

pub fn main(init: std.process.Init) !u8 {
    const io = init.io;
    const gpa = init.gpa;

    const args = try init.minimal.args.toSlice(init.arena.allocator());
    const port = parsePort(args) orelse {
        const name = if (args.len > 0) std.fs.path.basename(args[0]) else "kvhttp";
        std.debug.print("usage: {s} <port>\n", .{name});
        return 2;
    };

    var store: Store = .init(gpa);
    defer store.deinit();

    const address: net.IpAddress = .{ .ip4 = .loopback(port) };
    var server = try address.listen(io, .{ .reuse_address = true, .kernel_backlog = 1024 });
    defer server.deinit(io);

    var group: Io.Group = .init;
    defer group.cancel(io);

    while (true) {
        const stream = server.accept(io) catch |err| switch (err) {
            error.ConnectionAborted, error.ProtocolFailure => continue,
            error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded, error.SystemResources => {
                log.warn("accept failed: {t}", .{err});
                // Back off briefly so in-flight connections can finish and release resources.
                io.sleep(.fromMilliseconds(10), .awake) catch {};
                continue;
            },
            else => return err,
        };
        group.concurrent(io, serveConnection, .{ io, gpa, &store, stream }) catch |err| {
            log.warn("cannot spawn connection handler ({t}); serving inline", .{err});
            serveConnection(io, gpa, &store, stream);
        };
    }
}

fn parsePort(args: []const [:0]const u8) ?u16 {
    if (args.len != 2) return null;
    const text = args[1];
    if (text.len == 0) return null;
    for (text) |c| if (!std.ascii.isDigit(c)) return null;
    return std.fmt.parseInt(u16, text, 10) catch null;
}

fn serveConnection(io: Io, gpa: Allocator, store: *Store, stream: net.Stream) void {
    defer stream.close(io);
    handleConnection(io, gpa, store, stream) catch |err| switch (err) {
        error.ReadFailed, error.WriteFailed => {},
        error.OutOfMemory => log.err("out of memory while serving request", .{}),
    };
}

const ConnectionError = error{ ReadFailed, WriteFailed, OutOfMemory };

fn handleConnection(io: Io, gpa: Allocator, store: *Store, stream: net.Stream) ConnectionError!void {
    var arena_state: std.heap.ArenaAllocator = .init(gpa);
    defer arena_state.deinit();
    const arena = arena_state.allocator();

    const read_buffer = try arena.alloc(u8, read_buffer_size);
    const write_buffer = try arena.alloc(u8, write_buffer_size);
    var reader = stream.reader(io, read_buffer);
    var writer = stream.writer(io, write_buffer);

    var response: http.Response = undefined;
    var owned_body: []const u8 = "";
    defer gpa.free(owned_body);

    if (http.readRequest(arena, gpa, &reader.interface)) |maybe_request| {
        const request = maybe_request orelse return;
        response = routes.handle(store, io, gpa, request) catch |err| switch (err) {
            error.OutOfMemory => .{ .status = .internal_server_error },
        };
        owned_body = response.body;
    } else |err| {
        // A null status means the connection itself failed; nothing can be sent.
        response = .{ .status = http.errorStatus(err) orelse return error.ReadFailed };
    }

    try response.write(&writer.interface);
}

test {
    _ = http;
    _ = routes;
    _ = Store;
}

test parsePort {
    try std.testing.expectEqual(@as(?u16, 8080), parsePort(&.{ "app", "8080" }));
    try std.testing.expectEqual(@as(?u16, null), parsePort(&.{"app"}));
    try std.testing.expectEqual(@as(?u16, null), parsePort(&.{ "app", "-1" }));
    try std.testing.expectEqual(@as(?u16, null), parsePort(&.{ "app", "70000" }));
}

//! Maps requests to responses against the key-value store.

const std = @import("std");
const Io = std.Io;
const Allocator = std.mem.Allocator;

const http = @import("http.zig");
const Store = @import("Store.zig");
const Request = http.Request;
const Response = http.Response;

const kv_prefix = "/kv/";
const max_key_len = 64;

/// Handles `req`. Takes ownership of `req.body`. Any response body is
/// allocated with `gpa` and owned by the caller.
pub fn handle(store: *Store, io: Io, gpa: Allocator, req: Request) Allocator.Error!Response {
    const path = req.path;
    if (std.mem.eql(u8, path, "/health")) {
        gpa.free(req.body);
        if (!isMethod(req, "GET")) return .{ .status = .method_not_allowed, .allow = "GET" };
        return .{ .status = .ok, .body = try gpa.dupe(u8, "ok"), .content_type = "text/plain" };
    }
    if (std.mem.eql(u8, path, "/kv")) {
        gpa.free(req.body);
        if (!isMethod(req, "GET")) return .{ .status = .method_not_allowed, .allow = "GET" };
        return .{ .status = .ok, .body = try store.keysJson(io, gpa), .content_type = "application/json" };
    }
    if (std.mem.startsWith(u8, path, kv_prefix)) {
        const key = path[kv_prefix.len..];
        if (!isValidKey(key)) {
            gpa.free(req.body);
            return .{ .status = .bad_request };
        }
        return handleKey(store, io, gpa, req, key);
    }
    gpa.free(req.body);
    return .{ .status = .not_found };
}

fn handleKey(store: *Store, io: Io, gpa: Allocator, req: Request, key: []const u8) Allocator.Error!Response {
    if (isMethod(req, "PUT")) {
        const created = try store.put(io, key, req.body);
        return .{ .status = if (created) .created else .ok };
    }
    gpa.free(req.body);
    if (isMethod(req, "GET")) {
        const value = try store.getCopy(io, gpa, key) orelse return .{ .status = .not_found };
        return .{ .status = .ok, .body = value };
    }
    if (isMethod(req, "DELETE")) {
        return .{ .status = if (store.delete(io, key)) .no_content else .not_found };
    }
    return .{ .status = .method_not_allowed, .allow = "GET, PUT, DELETE" };
}

fn isMethod(req: Request, method: []const u8) bool {
    return std.mem.eql(u8, req.method, method);
}

pub fn isValidKey(key: []const u8) bool {
    if (key.len == 0 or key.len > max_key_len) return false;
    for (key) |c| switch (c) {
        'A'...'Z', 'a'...'z', '0'...'9', '_', '-' => {},
        else => return false,
    };
    return true;
}

const testing = std.testing;

fn call(store: *Store, method: []const u8, path: []const u8, body: []const u8) !Response {
    return handle(store, testing.io, testing.allocator, .{
        .method = method,
        .path = path,
        .body = try testing.allocator.dupe(u8, body),
    });
}

fn expectStatus(store: *Store, status: http.Status, method: []const u8, path: []const u8, body: []const u8) !void {
    const res = try call(store, method, path, body);
    defer testing.allocator.free(res.body);
    try testing.expectEqual(status, res.status);
}

test "key validation" {
    try testing.expect(isValidKey("a"));
    try testing.expect(isValidKey("A-z_09"));
    try testing.expect(isValidKey("k" ** 64));
    try testing.expect(!isValidKey(""));
    try testing.expect(!isValidKey("k" ** 65));
    try testing.expect(!isValidKey("a/b"));
    try testing.expect(!isValidKey("bad.key"));
    try testing.expect(!isValidKey("caf\xc3\xa9"));
}

test "routes" {
    var store: Store = .init(testing.allocator);
    defer store.deinit();

    try expectStatus(&store, .ok, "GET", "/health", "");
    try expectStatus(&store, .method_not_allowed, "POST", "/health", "");
    try expectStatus(&store, .not_found, "GET", "/nope", "");
    try expectStatus(&store, .not_found, "GET", "/health/", "");
    try expectStatus(&store, .bad_request, "GET", "/kv/", "");
    try expectStatus(&store, .bad_request, "PATCH", "/kv/a.b", "");
    try expectStatus(&store, .method_not_allowed, "POST", "/kv", "");
    try expectStatus(&store, .created, "PUT", "/kv/a", "hello");
    try expectStatus(&store, .ok, "PUT", "/kv/a", "world");
    try expectStatus(&store, .method_not_allowed, "PATCH", "/kv/a", "");

    const got = try call(&store, "GET", "/kv/a", "");
    defer testing.allocator.free(got.body);
    try testing.expectEqualStrings("world", got.body);

    const list = try call(&store, "GET", "/kv", "");
    defer testing.allocator.free(list.body);
    try testing.expectEqualStrings("[\"a\"]", list.body);
    try testing.expectEqualStrings("application/json", list.content_type.?);

    try expectStatus(&store, .no_content, "DELETE", "/kv/a", "");
    try expectStatus(&store, .not_found, "DELETE", "/kv/a", "");
    try expectStatus(&store, .not_found, "GET", "/kv/a", "");
}
